// 📁 src/app/core/models/search.interface.ts
// 🔍 INTERFACES SIMPLIFICADAS PARA BÚSQUEDA EN UN SOLO LUGAR

import { PropertyType, AmenityType, ServiceType } from './property.interface';

// 🔍 PARÁMETROS DE BÚSQUEDA SIMPLIFICADOS
export interface SearchParams {
  checkIn: string;
  checkOut: string;
  guests: number;
  roomType?: PropertyType; // Opcional: tipo de habitación preferido
}

// 🎛️ FILTROS POR TIPO DE HABITACIÓN
export interface PropertyTypeFilters {
  habitacion: boolean;
  suite: boolean;
  apartamento: boolean;
  studio: boolean;
}

// 🎛️ FILTROS POR AMENIDADES
export interface AmenityFilters {
  wifi: boolean;
  parking: boolean;
  breakfast: boolean;
  kitchen: boolean;
  ac: boolean;
  tv: boolean;
  'washing-machine': boolean;
  security: boolean;
  elevator: boolean;
  balcony: boolean;
}

// 🛎️ FILTROS POR SERVICIOS
export interface ServiceFilters {
  cleaning: boolean;
  transport: boolean;
  'luggage-storage': boolean;
  concierge: boolean;
  'tour-info': boolean;
  'late-checkin': boolean;
}

// ⏰ FILTROS POR DURACIÓN DE ESTANCIA
export interface StayDurationFilters {
  shortTerm: boolean; // 1-6 noches
  weekly: boolean;    // 7-29 noches
  monthly: boolean;   // 30+ noches
}

// 🎛️ FILTROS PRINCIPALES SIMPLIFICADOS
export interface Filters {
  propertyTypes: PropertyTypeFilters;
  amenities: AmenityFilters;
  services: ServiceFilters;
  stayDuration: StayDurationFilters;
  minRating: number;
  priceMin: number;
  priceMax: number;
  maxGuests: number;
  instantBook: boolean;
  verified: boolean;
  available: boolean; // Nuevo: solo habitaciones disponibles
}

// 📊 ESTADO DE FILTROS
export interface FilterState {
  activeFilters: Filters;
  hasActiveFilters: boolean;
  filterCount: number;
}

// 🔄 OPCIONES DE ORDENAMIENTO
export interface SortOption {
  value: string;
  label: string;
  icon?: string;
}

export const SORT_OPTIONS: SortOption[] = [
  { value: 'price-asc', label: 'Precio: Menor a Mayor', icon: '💰' },
  { value: 'price-desc', label: 'Precio: Mayor a Menor', icon: '💎' },
  { value: 'rating', label: 'Mejor Calificadas', icon: '⭐' },
  { value: 'reviews', label: 'Más Reseñas', icon: '💬' },
  { value: 'capacity', label: 'Mayor Capacidad', icon: '👥' },
  { value: 'newest', label: 'Más Recientes', icon: '🆕' },
  { value: 'relevance', label: 'Más Relevantes', icon: '🎯' }
];

// ⚙️ CONFIGURACIÓN DE RESULTADOS
export interface SearchResultsConfig {
  viewMode: 'grid' | 'list';
  sortBy: string;
  itemsPerPage: number;
  currentPage: number;
  showComparison: boolean;
}

// 💡 SUGERENCIAS RÁPIDAS PARA HABITACIONES
export interface RoomSuggestion {
  roomType: PropertyType;
  label: string;
  icon: string;
  description: string;
  priceRange: string;
}

export const ROOM_SUGGESTIONS: RoomSuggestion[] = [
  {
    roomType: 'habitacion',
    label: 'Habitación Standard',
    icon: '🛏️',
    description: 'Cómoda y funcional',
    priceRange: '$45.000 - $65.000'
  },
  {
    roomType: 'suite',
    label: 'Suite Premium',
    icon: '⭐',
    description: 'Espacio extra y comodidades',
    priceRange: '$75.000 - $85.000'
  }
];

// 📈 TENDENCIAS DE BÚSQUEDA
export interface SearchTrend {
  period: string;
  popularRoomType: PropertyType;
  averageStay: number;
  peakDemand: string[];
}

// 📅 HISTORIAL DE BÚSQUEDA
export interface SearchHistoryItem {
  id: string;
  searchParams: SearchParams;
  timestamp: Date;
  resultsCount: number;
  selectedRoom?: string;
}

// ================================
// 🔧 CONFIGURACIONES POR DEFECTO
// ================================

export const DEFAULT_SEARCH_PARAMS: SearchParams = {
  checkIn: '',
  checkOut: '',
  guests: 2
};

export const DEFAULT_FILTERS: Filters = {
  propertyTypes: {
    habitacion: false,
    suite: false,
    apartamento: false,
    studio: false
  },
  amenities: {
    wifi: false,
    parking: false,
    breakfast: false,
    kitchen: false,
    ac: false,
    tv: false,
    'washing-machine': false,
    security: false,
    elevator: false,
    balcony: false
  },
  services: {
    cleaning: false,
    transport: false,
    'luggage-storage': false,
    concierge: false,
    'tour-info': false,
    'late-checkin': false
  },
  stayDuration: {
    shortTerm: false,
    weekly: false,
    monthly: false
  },
  minRating: 0,
  priceMin: 0,
  priceMax: 100000,
  maxGuests: 10,
  instantBook: false,
  verified: false,
  available: true // Por defecto solo mostrar disponibles
};

export const DEFAULT_SEARCH_RESULTS_CONFIG: SearchResultsConfig = {
  viewMode: 'grid',
  sortBy: 'price-asc',
  itemsPerPage: 5, // Solo 5 habitaciones
  currentPage: 1,
  showComparison: false
};

// 💰 RANGOS DE PRECIO ESPECÍFICOS
export const PRICE_RANGES = [
  { min: 0, max: 50000, label: 'Hasta $50.000', category: 'económico' },
  { min: 50000, max: 70000, label: '$50.000 - $70.000', category: 'standard' },
  { min: 70000, max: 90000, label: '$70.000 - $90.000', category: 'superior' },
  { min: 90000, max: 999999, label: 'Más de $90.000', category: 'premium' }
];

// ⭐ FILTROS DE CALIFICACIÓN
export const RATING_FILTERS = [
  { value: 0, label: 'Cualquier calificación' },
  { value: 4.0, label: '4.0+ Muy buena' },
  { value: 4.5, label: '4.5+ Excelente' },
  { value: 4.8, label: '4.8+ Excepcional' }
];

// 👥 OPCIONES DE CAPACIDAD
export const GUEST_OPTIONS = [
  { value: 1, label: '1 huésped' },
  { value: 2, label: '2 huéspedes' },
  { value: 3, label: '3+ huéspedes' }
];

// 🎯 FILTROS PREESTABLECIDOS
export const QUICK_FILTERS = {
  business: {
    name: 'Viaje de negocios',
    icon: '💼',
    filters: {
      amenities: { wifi: true, ac: true },
      services: { 'late-checkin': true },
      verified: true
    }
  },
  budget: {
    name: 'Económico',
    icon: '💰',
    filters: {
      priceMax: 50000,
      verified: true
    }
  },
  comfort: {
    name: 'Máximo confort',
    icon: '⭐',
    filters: {
      minRating: 4.5,
      amenities: { ac: true, balcony: true },
      services: { cleaning: true, concierge: true }
    }
  },
  instant: {
    name: 'Reserva inmediata',
    icon: '⚡',
    filters: {
      instantBook: true,
      available: true
    }
  }
};

// ================================
// 🛠️ FUNCIONES UTILITARIAS
// ================================

export const calculateNights = (checkIn: string, checkOut: string): number => {
  if (!checkIn || !checkOut) return 0;
  
  const checkInDate = new Date(checkIn);
  const checkOutDate = new Date(checkOut);
  const timeDiff = checkOutDate.getTime() - checkInDate.getTime();
  return Math.ceil(timeDiff / (1000 * 3600 * 24));
};

export const getStayCategory = (nights: number): keyof StayDurationFilters => {
  if (nights >= 30) return 'monthly';
  if (nights >= 7) return 'weekly';
  return 'shortTerm';
};

export const isWeekend = (date: string): boolean => {
  const day = new Date(date).getDay();
  return day === 0 || day === 6; // Domingo o Sábado
};

export const getSeasonality = (date: string): 'alta' | 'media' | 'baja' => {
  const month = new Date(date).getMonth() + 1;
  
  // Temporada alta: Diciembre, Enero, Semana Santa, Junio-Julio
  if ([12, 1, 6, 7].includes(month)) return 'alta';
  
  // Temporada media: Marzo, Abril, Noviembre
  if ([3, 4, 11].includes(month)) return 'media';
  
  return 'baja';
};
